import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, mix, color, vec3, float, hash, positionLocal } from 'three/tsl';
import * as THREE from 'three/webgpu';
import gsap from 'gsap';

export default function createNode(config, ctx) {
  const group = new THREE.Object3D();
  group.name = 'kinetic-hero-headline';

  const disposables = [];
  const timelines = [];

  // ---- Backdrop plane ----
  const bgMat = new MeshBasicNodeMaterial();
  const vUv = uv();
  const topColor = color(0x0b0b10);
  const botColor = color(0x13131a);
  const grain = hash(vUv.mul(1000.0)).sub(0.5).mul(0.015);
  bgMat.colorNode = mix(topColor, botColor, vUv.y).add(vec3(grain, grain, grain));
  const bgGeo = new THREE.PlaneGeometry(7, 5.5);
  const bgMesh = new THREE.Mesh(bgGeo, bgMat);
  bgMesh.position.set(0, 0, -1.5);
  group.add(bgMesh);
  disposables.push(bgGeo, bgMat);

  // ---- Caption kicker ----
  const captionText = ctx.fontAtlas.createText({
    text: 'NOVA ATELIER / CALIBRE PROGRAM',
    fontFamily: 'JetBrains Mono',
    fontWeight: 700,
    emHeight: 0.09,
    letterSpacing: 0.12,
    color: 0xe8ecf2,
    align: 'center',
  });
  captionText.position.set(0, 1.15, 0);
  group.add(captionText);
  disposables.push(captionText);

  // ---- Hero headline (kinetic per-glyph) ----
  const heroText = ctx.fontAtlas.createText({
    text: 'TIME, MACHINED.',
    fontFamily: 'Lora',
    fontWeight: 600,
    emHeight: 0.62,
    letterSpacing: -0.01,
    color: 0xe8ecf2,
    align: 'center',
    perGlyph: true,
  });
  heroText.position.set(0, 0.4, 0);
  group.add(heroText);
  disposables.push(heroText);

  // per-word z parallax offset (front/mid/back thirds)
  const glyphs = heroText.userData.glyphs || heroText.children || [];
  const glyphCount = glyphs.length;
  glyphs.forEach((g, i) => {
    const t = glyphCount > 1 ? i / (glyphCount - 1) : 0;
    const z = t < 0.34 ? 0.12 : t < 0.67 ? 0.0 : -0.12;
    g.position.z = z;
    g.userData.baseY = g.position.y;
    g.userData.baseZ = z;
  });

  // ---- Accent underline rule ----
  const underlineMat = new MeshStandardNodeMaterial();
  underlineMat.color = new THREE.Color(0xff2a38);
  underlineMat.emissive = new THREE.Color(0xff2a38);
  underlineMat.emissiveIntensity = 1.2;
  underlineMat.roughness = 0.5;
  underlineMat.metalness = 0.3;
  const underlineGeo = new THREE.PlaneGeometry(2.6, 0.045);
  underlineGeo.translate(1.3, 0, 0); // anchor left for scaleX pivot
  const underline = new THREE.Mesh(underlineGeo, underlineMat);
  underline.position.set(-1.3, -0.05, 0);
  underline.scale.x = 0.0001;
  group.add(underline);
  disposables.push(underlineGeo, underlineMat);

  // ---- Subhead ----
  const subheadText = ctx.fontAtlas.createText({
    text: 'Every calibre begins as a solid billet.',
    fontFamily: 'JetBrains Mono',
    fontWeight: 400,
    emHeight: 0.2,
    letterSpacing: 0.02,
    color: 0xe8ecf2,
    align: 'center',
  });
  subheadText.position.set(0, -0.65, 0);
  subheadText.material && (subheadText.material.transparent = true);
  group.add(subheadText);
  disposables.push(subheadText);

  // set initial hidden states for fade-up elements
  const setOpacity = (obj, v) => {
    obj.traverse((o) => {
      if (o.material) {
        o.material.transparent = true;
        if (o.material.opacity !== undefined) o.material.opacity = v;
      }
    });
  };
  setOpacity(subheadText, 0);
  subheadText.position.y -= 0.2;

  // ---- Apply cinematic primitive: kinetic-text ----
  const primitiveParams = { staggerMs: 60, riseUnits: 0.35 };
  const kineticPrimitive = config.cinematicPrimitives?.find((p) => p.name === 'kinetic-text');
  if (kineticPrimitive && ctx.primitives['kinetic-text']) {
    ctx.primitives['kinetic-text'](heroText, {
      ...primitiveParams,
      ...kineticPrimitive.params,
      onComplete: () => runFollowUpAnimations(),
    });
  } else {
    runFollowUpAnimations();
  }

  function runFollowUpAnimations() {
    // weighted-settle on hero group
    const settleTl = gsap.timeline();
    heroText.scale.set(1.04, 1.04, 1.04);
    settleTl.to(heroText.scale, {
      x: 1, y: 1, z: 1,
      duration: 0.9,
      ease: 'power4.out',
    });
    timelines.push(settleTl);

    // underline scaleX 0 -> 1, starting 120ms after last glyph lands
    const underlineTl = gsap.timeline({ delay: 0.12 });
    underlineTl.to(underline.scale, {
      x: 1,
      duration: 0.5,
      ease: 'power2.out',
    });
    timelines.push(underlineTl);

    // subhead fade-up
    const subheadTl = gsap.timeline({ delay: 0.12 });
    subheadTl.to(subheadText.position, {
      y: -0.65,
      duration: 0.5,
      ease: 'power2.out',
    }, 0);
    setOpacity(subheadText, 0);
    const proxy = { o: 0 };
    subheadTl.to(proxy, {
      o: 1,
      duration: 0.5,
      ease: 'power2.out',
      onUpdate: () => setOpacity(subheadText, proxy.o),
    }, 0);
    timelines.push(subheadTl);
  }

  group.userData.handlers = {};

  group.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    disposables.forEach((d) => {
      if (d && typeof d.dispose === 'function') d.dispose();
      if (d && d.userData && typeof d.userData.cleanup === 'function') d.userData.cleanup();
    });
    bgGeo.dispose();
    bgMat.dispose();
    underlineGeo.dispose();
    underlineMat.dispose();
  };

  return group;
}
